
import numpy as np, math
DESCRIPTION = ("Exact wiring of the 2-layer attention-only transformer in compressed form: token+position embeddings, then per layer a "
 "softmax attention with score x S x^T (S = W_Q W_K^T, one 8x8 table) whose output (p@x) V (V = W_V W_O, one 8x8 table) is added to the "
 "residual stream; the last position's residual is read out by W_U. Named variables: the last-position token (embedding stage), the "
 "layer-1 attention row at the last position (pattern stage) and the last position's residual slice (readout stage). Note the readout is "
 "dominated by a large constant offset produced by the layer-1 attention, which is why the network answers class 5 in 94% of inputs.")
E=np.array([[1.1128,-0.315,-1.6105,-1.3029,0.4189,1.3427,0.4039,0.2747],[-0.1057,-0.8274,-0.2466,0.1872,0.4492,-0.1577,-0.0833,0.3764],[0.4413,0.3314,0.9552,0.2846,0.015,0.9523,-0.3522,-0.0687],[-0.1973,0.9065,-1.0912,-0.6097,-0.1798,2.18,-1.062,0.4638],[-0.7205,-0.2665,0.4021,-2.0123,0.1993,0.4371,0.0198,-0.0918],[0.2904,-0.1818,-0.2368,1.1441,-0.0398,0.0922,0.2485,0.2163]])
