V0=np.array([[0.6749,0.0231,0.3189,-0.7475,0.4224,-0.4162,0.0598,0.1129],[-0.2068,0.2855,0.5636,-0.1625,0.3824,-0.412,0.0883,-0.1811],[0.0336,0.1454,-0.2455,-0.0125,-0.2585,0.2362,0.1444,-0.0389],[-0.283,-0.5129,1.0718,0.9159,0.2801,0.0064,-0.6208,0.0763],[0.4803,1.1176,-1.4435,-1.6174,0.1483,-0.1291,0.8296,0.0236],[-0.4728,-0.0434,-0.8199,-0.3461,-0.709,-0.2992,0.8028,-0.455],[-0.2189,-0.0029,0.6914,0.3418,-0.1878,-0.4817,-0.1057,-0.4148],[0.0341,0.0564,-0.9304,-1.1074,0.0837,-0.7523,0.4538,-0.1621]])
S1=np.array([[-0.018,-0.37,-0.2378,0.2132,-0.7707,-0.2254,0.6555,-0.6381],[-1.7687,-0.8886,1.6962,1.8755,-1.3023,1.2029,0.485,-0.1094],[0.6636,-1.1542,0.0264,-0.7766,-0.4936,-1.0823,0.443,0.3165],[0.6686,-0.7148,-0.968,-1.2662,-0.0264,-0.7329,0.0394,0.0055],[0.001,-1.0153,-1.309,-0.1923,-0.4942,-1.819,-0.1143,-1.378],[1.0968,0.4643,-2.9199,-0.9447,2.6586,-0.1628,-0.1077,0.6918],[0.9715,0.8623,-1.3601,-1.1214,-0.6495,0.0255,-0.1664,-2.0727],[-0.9582,1.3097,0.2442,0.4055,-0.0401,0.4106,-0.7001,-0.2058]])
